def zero_components(grid,connect=4):
 pts={(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==0}; cs=[]
 steps=[(-1,0),(1,0),(0,-1),(0,1)]
 if connect==8: steps += [(-1,-1),(-1,1),(1,-1),(1,1)]
 while pts:
  p=pts.pop(); comp={p}; st=[p]
  while st:
   r,c=st.pop()
   for dr,dc in steps:
    q=r+dr,c+dc
    if q in pts: pts.remove(q);comp.add(q);st.append(q)
  cs.append(comp)
 return cs
